mapper.select:
SELECT Count(*)
FROM   TBLMI_USR AS usr
	LEFT JOIN TBLMI_USR_AUTH AS auth
			ON auth.usr_id = usr.usr_id
	LEFT JOIN TBLMI_COMM_CD AS cd
			ON cd.cd_id = auth.role_cd
	LEFT JOIN TBLMI_USR AS infoApp
			ON infoApp.usr_id = usr.appr_id
			AND infoApp.usr_grp_cd = #{usr_grp_cd}
WHERE  cd.grp_id = 'ROLE_CD'

		and usr.usr_grp_cd = #{usr_grp_cd}


		and usr.seq = #{seq}


		and usr.usr_email = #{usr_email}


		and usr.usr_nm = #{usr_nm}


		and usr.usr_mob = #{usr_mob}


		and usr.usr_id = #{usr_id}

select usr.seq , usr.usr_id , usr.usr_log_id , usr.usr_email , usr.usr_pw , usr.usr_grp_cd , usr.usr_nm , usr.usr_tel , usr.usr_mob , usr.usr_st , usr.appr_id , infoApp.usr_email as appr_email , usr.access_yn , usr.last_log_in_dt , usr.last_pw_upd_dt , usr.reg_id , usr.reg_dt , usr.upd_id , usr.upd_dt , auth.role_cd , cd.cd_nm from tblmi_usr as usr LEFT JOIN tblmi_usr_auth as auth on auth.usr_id = usr.usr_id LEFT JOIN tblmi_comm_cd as cd on cd.cd_id = auth.role_cd LEFT JOIN tblmi_usr as infoApp on infoApp.usr_id = usr.appr_id and infoApp.usr_grp_cd = #{usr_grp_cd} where cd.grp_id = 'ROLE_CD'
and usr.usr_grp_cd = #{usr_grp_cd}
and usr.seq = #{seq}
and usr.usr_email = #{usr_email}
and usr.usr_nm = #{usr_nm}
and usr.usr_mob = #{usr_mob}
and usr.usr_id = #{usr_id}
order by usr.REG_DT DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

SELECT Count(*)
FROM   TBLMI_USR_LOG_HST
	where
		usr_grp_cd = #{usr_grp_cd}
		and usr_email = #{usr_email}

mapper.update:
update tblmi_usr_auth set

	role_cd=#{role_cd},

	UPD_DT = now(), UPD_ID=#{upd_id}
where
	usr_id = #{usr_id}
